INSERT INTO policy_templates (id, tenant_id, name, slug, framework, category, body, version, status, is_system, created_by, approved_by, created_at, updated_at) VALUES ('c4bdc66f-d31e-5953-bd0e-ed76e8470050', 'system', 'Access Control Policy', 'access-control-policy', 'SOC 2', 'governance', E'# Access Control Policy\n\n## 1. Purpose\n\nThis policy establishes requirements for access control policy within the SOC 2 framework. It provides authoritative guidance for all personnel responsible for implementing and maintaining these controls.\n\n## 2. Scope\n\nApplies to all employees, contractors, and third-party providers who access organizational systems and data across all environments.\n\n## 3. Policy Statements\n\n3.1 The organization shall implement controls as specified in SOC 2 requirements.\n3.2 All personnel must comply with standards defined herein.\n3.3 Regular assessments shall verify compliance.\n3.4 Non-compliance triggers corrective action.\n3.5 Exceptions require documented approval.\n\n## 4. Roles and Responsibilities\n\n| Role | Responsibility |\n|---|---|\n| Policy Owner | Maintains and updates this policy |\n| CISO | Oversight and approval |\n| Department Heads | Team compliance |\n| All Employees | Adherence to requirements |\n\n## 5. Compliance Requirements\n\nMaps to SOC 2 controls. Evidence must be collected and retained per schedule.\n\n## 6. Review and Update\n\nReviewed annually or upon significant changes.\n\n## 7. Document Control\n\n| Field | Value |\n|---|---|\n| Version | 1.0.0 |\n| Classification | Internal |\n| Author | Sentinel Policy Engine |\n| Approver | System Administrator |', '1.0.0', 'APPROVED', TRUE, 'system', 'system', NOW(), NOW());
